import { Cause, Clock, Context, Data, Effect, ErrorReporter, Layer, Match, Redacted } from "effect";
import { SecureRandom } from "effect/crypto";
import {
  HttpEffect,
  HttpRouter,
  HttpServerError,
  HttpServerRequest,
  HttpServerRespondable,
  HttpServerResponse,
} from "effect/http";
import type { TwitchHttpErrorBody } from "@cf-twitch/contracts/twitch-api";

/** Server-owned identifiers that correlate one HTTP request with its logs, traces, and error body. */
export interface IHttpRequestCorrelation {
  /** Random UUID generated by the server for this request; returned in `x-request-id` and every error body. */
  readonly requestId: string;
  /** Trace ID of the request's server span; returned in `x-trace-id`. */
  readonly traceId: string;
}

/** Request correlation identifiers, generated by the server and never accepted from request headers. */
export class HttpRequestCorrelation extends Context.Service<
  HttpRequestCorrelation,
  IHttpRequestCorrelation
>()("@cf-twitch/HttpRequestCorrelation") {}

/**
 * Creates request correlation from a fresh random request ID and the current span's trace ID.
 *
 * **Details**
 *
 * The public HTTP middleware runs this once per request inside the server span.
 *
 * @throws {NoSuchElementError} As a defect when no span is active, because the trace ID cannot be correlated.
 */
export const makeHttpRequestCorrelation = Effect.gen(function* () {
  const secureRandom = yield* SecureRandom.SecureRandom;
  const span = yield* Effect.currentSpan.pipe(Effect.orDie);
  const requestId = yield* secureRandom.uuidV4();

  return HttpRequestCorrelation.of({ requestId, traceId: span.traceId });
});

/** Layer that creates request correlation from the platform `SecureRandom` service and the current span. */
export const httpRequestCorrelationLayerWithoutDependencies = Layer.effect(
  HttpRequestCorrelation,
  makeHttpRequestCorrelation,
);

/** Production request correlation Layer; `SecureRandom` is a Worker platform service selected by the root. */
export const httpRequestCorrelationLayer = httpRequestCorrelationLayerWithoutDependencies;

/** Request ID reported by {@link httpRequestCorrelationTestLayer}. */
export const httpRequestCorrelationTestRequestId = "00000000-0000-4000-8000-000000000000";

/** Layer with fixed, well-formed correlation identifiers for handler tests that run without the middleware. */
export const httpRequestCorrelationTestLayer = Layer.succeed(
  HttpRequestCorrelation,
  HttpRequestCorrelation.of({
    requestId: httpRequestCorrelationTestRequestId,
    traceId: "00000000000000000000000000000000",
  }),
);

/** Root-level classification of a failed request: an unexpected defect or an expected framework rejection. */
type HttpTraceFailureClassification = "defect" | "expected_http_failure";

/** Error reported for a failed request; it carries only safe correlation, and redacts the original cause. */
class HttpTraceFailure
  extends Data.TaggedError("HttpTraceFailure")<{
    readonly operation: "handleRequest";
    readonly reason: HttpTraceFailureClassification;
    readonly redactedCause: Redacted.Redacted<Cause.Cause<unknown>>;
    readonly requestId: string;
    readonly response: HttpServerResponse.HttpServerResponse;
    readonly traceId: string;
  }>
  implements HttpServerRespondable.Respondable
{
  override readonly [ErrorReporter.ignore] = this.reason === "expected_http_failure";
  override readonly [ErrorReporter.severity] = "Error" as const;
  override readonly [ErrorReporter.attributes] = {
    "http.failure.classification": this.reason,
    "http.response.status_code": this.response.status,
    request_id: this.requestId,
    trace_id: this.traceId,
  };

  override get message(): string {
    return `HTTP request failed during ${this.operation} (${this.reason}). Inspect the logs and trace for request ID ${this.requestId}.`;
  }

  [HttpServerRespondable.symbol]() {
    return Effect.succeed(this.response);
  }
}

/** Renders the safe public body for an unexpected defect; the cause stays in the redacted error report. */
const renderInternalFailure = (requestId: string): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.jsonUnsafe(
    {
      code: "InternalFailure",
      error: "Internal server error",
      operation: "handleRequest",
      message: `Internal server error while handling the request. Contact support with request ID ${requestId}.`,
      details: {},
      requestId,
      retryable: false,
    } satisfies TwitchHttpErrorBody,
    { status: 500 },
  );

/** Renders framework routing and request-reading rejections with the public error envelope. */
const renderHttpServerError = (
  error: HttpServerError.HttpServerError,
  requestId: string,
  method: string,
  path: string,
): HttpServerResponse.HttpServerResponse =>
  Match.value(error.reason).pipe(
    Match.tagsExhaustive({
      RouteNotFound: () =>
        HttpServerResponse.jsonUnsafe(
          {
            code: "RouteNotFound",
            error: "Not found",
            operation: "routeRequest",
            message: `No route matches ${method} ${path}. Check the method and path against the API documentation.`,
            details: { method, path },
            requestId,
            retryable: false,
          } satisfies TwitchHttpErrorBody,
          { status: 404 },
        ),
      RequestParseError: () =>
        HttpServerResponse.jsonUnsafe(
          {
            code: "InvalidJsonBody",
            error: "Invalid request body",
            operation: "routeRequest",
            message: `Request body for ${method} ${path} could not be read. Fix the body and send the request again.`,
            details: {},
            requestId,
            retryable: false,
          } satisfies TwitchHttpErrorBody,
          { status: 400 },
        ),
      InternalError: () => renderInternalFailure(requestId),
      ResponseError: () => renderInternalFailure(requestId),
    }),
  );

/** Safe server tracing omits header values, full URLs, query values and response Location credentials. */
export const twitchHttpCorrelationLayer = HttpRouter.middleware<{
  provides: HttpRequestCorrelation;
  handles: HttpServerError.HttpServerError;
}>()(
  Effect.gen(function* () {
    const secureRandom = yield* SecureRandom.SecureRandom;

    return (httpEffect) =>
      Effect.gen(function* () {
        const request = yield* HttpServerRequest.HttpServerRequest;
        const url = new URL(request.originalUrl, "https://http.internal");
        const startedAt = yield* Clock.currentTimeMillis;

        return yield* Effect.gen(function* () {
          const correlation = yield* makeHttpRequestCorrelation.pipe(
            Effect.provideService(SecureRandom.SecureRandom, secureRandom),
          );

          const { requestId, traceId } = correlation;

          const annotations = {
            request_id: requestId,
            "cf_twitch.runtime.component": "api-worker",
          };

          yield* Effect.annotateCurrentSpan(annotations);
          yield* Effect.logInfo("HTTP request received").pipe(
            Effect.annotateLogs({
              event: "http.request.received",
              request_id: requestId,
              trace_id: traceId,
              method: request.method,
              path: url.pathname,
              query_keys: [...url.searchParams.keys()].sort(),
            }),
          );
          yield* HttpEffect.appendPreResponseHandler((_request, response) =>
            Effect.succeed(
              HttpServerResponse.setHeaders(response, {
                "x-request-id": requestId,
                "x-trace-id": traceId,
              }),
            ),
          );

          const completeRequest = (status: number) =>
            Effect.gen(function* () {
              yield* Effect.annotateCurrentSpan("http.response.status_code", status);
              const completedAt = yield* Clock.currentTimeMillis;
              yield* Effect.logInfo("HTTP request completed").pipe(
                Effect.annotateLogs({
                  event: "http.request.completed",
                  status_code: status,
                  duration_ms: completedAt - startedAt,
                }),
              );
            });

          const failHttpTrace = <E>(
            response: HttpServerResponse.HttpServerResponse,
            reason: HttpTraceFailureClassification,
            cause: Cause.Cause<E>,
          ) => {
            const failure = new HttpTraceFailure({
              operation: "handleRequest",
              reason,
              redactedCause: Redacted.make(cause),
              requestId,
              response,
              traceId,
            });

            const safeCause = Cause.fromReasons([
              Cause.makeFailReason(failure),
              ...cause.reasons.filter(Cause.isInterruptReason),
            ]);

            return Effect.annotateCurrentSpan("http.failure.classification", reason).pipe(
              Effect.andThen(completeRequest(response.status)),
              Effect.andThen(Effect.failCause(safeCause)),
            );
          };

          return yield* httpEffect.pipe(
            Effect.provideService(HttpRequestCorrelation, correlation),
            Effect.catchCauseIf(Cause.hasDies, (cause) =>
              failHttpTrace(renderInternalFailure(requestId), "defect", cause),
            ),
            Effect.catchTag("HttpServerError", (error) =>
              failHttpTrace(
                renderHttpServerError(error, requestId, request.method, url.pathname),
                "expected_http_failure",
                Cause.fail(error),
              ),
            ),
            Effect.tap((response) => completeRequest(response.status)),
            Effect.annotateSpans(annotations),
            Effect.annotateLogs({ request_id: requestId, trace_id: traceId }),
          );
        }).pipe(
          Effect.withSpan("HTTP request", {
            kind: "server",
            attributes: { "http.request.method": request.method, "url.path": url.pathname },
          }),
          Effect.withErrorReporting,
          Effect.catchTag("HttpTraceFailure", (failure) => {
            const interrupts = Redacted.value(failure.redactedCause).reasons.filter(
              Cause.isInterruptReason,
            );

            return interrupts.length > 0
              ? Effect.failCause(
                  Cause.fromReasons<never>([Cause.makeDieReason(failure), ...interrupts]),
                )
              : Effect.succeed(failure.response);
          }),
        );
      });
  }),
  { global: true },
);
